begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values ('d1111111-1111-4111-8111-111111111111','refund-guardian@example.com'),('d2222222-2222-4222-8222-222222222222','refund-other@example.com');
update public.profiles set role='guardian' where id in ('d1111111-1111-4111-8111-111111111111','d2222222-2222-4222-8222-222222222222');
insert into public.wallet_transactions(kind,status,to_user_id,from_bucket,to_bucket,points,krw_amount,provider,provider_order_id,provider_payment_key,idempotency_key)
values('topup_confirmed','posted','d1111111-1111-4111-8111-111111111111','external','topup',10000,10000,'toss','refund_original_order','refund_original_payment','refund-original-fixture');
select ok(not has_function_privilege('authenticated','public.prepare_topup_refund(uuid,uuid,text,jsonb)','EXECUTE'),'client cannot mark provider dispatch');
select ok(not has_function_privilege('anon','public.prepare_topup_refund(uuid,uuid,text,jsonb)','EXECUTE'),'anon cannot mark provider dispatch');
select ok(has_function_privilege('service_role','public.prepare_topup_refund(uuid,uuid,text,jsonb)','EXECUTE'),'service can mark provider dispatch');
select is((public.reserve_latest_topup_refund('d1111111-1111-4111-8111-111111111111','refund-recovery-first',3000)->>'originalAmount')::bigint,10000::bigint,'original amount comes from ledger');
select is((public.get_wallet_balances('d1111111-1111-4111-8111-111111111111')->>'topupAvailable')::bigint,7000::bigint,'reserve reduces available funds before provider cancel');
select is((public.reserve_latest_topup_refund('d1111111-1111-4111-8111-111111111111','refund-recovery-first',3000)->>'status'),'reserved','same key recovers reserved request');
select throws_ok($$select public.reserve_latest_topup_refund('d1111111-1111-4111-8111-111111111111','refund-recovery-first',4000)$$,'P0001','idempotency key mismatch','amount cannot change');
select throws_ok($$select public.reserve_latest_topup_refund('d1111111-1111-4111-8111-111111111111','refund-recovery-second',3000)$$,'P0001','unresolved refund exists','new key cannot bypass uncertain refund');
create temporary table rr as select id from public.wallet_transactions where idempotency_key='refund-recovery-first';
select throws_ok($$select public.prepare_topup_refund('d2222222-2222-4222-8222-222222222222',(select id from rr),'provider_test','{"balanceAmount":10000,"transactionKeys":[]}'::jsonb)$$,'P0001','refund request not found','foreign owner cannot dispatch');
select throws_ok($$select public.prepare_topup_refund('d1111111-1111-4111-8111-111111111111',(select id from rr),'provider_test','{"balanceAmount":2000,"transactionKeys":[]}'::jsonb)$$,'P0001','invalid provider snapshot','provider remainder must cover requested cancel');
select is((public.prepare_topup_refund('d1111111-1111-4111-8111-111111111111',(select id from rr),'provider_test','{"balanceAmount":10000,"transactionKeys":[]}'::jsonb)->>'canDispatch'),'true','first dispatch is allowed once');
select is((public.prepare_topup_refund('d1111111-1111-4111-8111-111111111111',(select id from rr),'provider_test','{"balanceAmount":7000,"transactionKeys":["different"]}'::jsonb)->>'canDispatch'),'false','retry cannot issue another cancel');
select is((select metadata->'providerSnapshot'->>'balanceAmount' from public.wallet_transactions where id=(select id from rr)),'10000','original provider snapshot cannot change on retry');
select throws_ok($$select public.prepare_topup_refund('d1111111-1111-4111-8111-111111111111',(select id from rr),'sandbox',null)$$,'P0001','refund mode mismatch','unknown provider cancel cannot switch to sandbox');
select throws_ok($$select public.reject_topup_refund('d1111111-1111-4111-8111-111111111111',(select id from rr))$$,'P0001','dispatched refund requires reconciliation','unknown dispatched outcome cannot release reserved funds');
select throws_ok($$select public.complete_topup_refund('d1111111-1111-4111-8111-111111111111',(select id from rr),'{}'::jsonb)$$,'P0001','provider refund incomplete','missing provider fields cannot bypass validation');
select throws_ok($$select public.complete_topup_refund('d1111111-1111-4111-8111-111111111111',(select id from rr),'{"status":"CANCELED","paymentKey":"refund_original_payment","cancelAmount":3000,"sandbox":true,"actualRefund":false}'::jsonb)$$,'P0001','provider refund incomplete','sandbox payload cannot settle provider dispatch');
create temporary table receipt as select jsonb_build_object('status','PARTIALLY_CANCELED','paymentKey','refund_original_payment','cancelAmount',3000,'transactionKey','refund_cancel_transaction','cancelReason','Mirujima refund '||id::text,'refundRequestId',id::text,'sandbox',false,'actualRefund',true,'providerMode','provider_test') payload from rr;
select throws_ok($$select public.complete_topup_refund('d1111111-1111-4111-8111-111111111111',(select id from rr),(select payload||'{"cancelAmount":4000}'::jsonb from receipt))$$,'P0001','provider refund incomplete','provider cancellation amount must match');
select is((public.complete_topup_refund('d1111111-1111-4111-8111-111111111111',(select id from rr),(select payload from receipt))->>'status'),'refunded','verified partial cancellation settles');
select is((public.complete_topup_refund('d1111111-1111-4111-8111-111111111111',(select id from rr),(select payload from receipt))->>'actualRefund'),'true','duplicate result preserves provider mode');
select is((select count(*) from public.wallet_transactions where related_transaction_id=(select id from rr) and kind='topup_refunded'),1::bigint,'one settlement across retries');
select is((public.reject_topup_refund('d1111111-1111-4111-8111-111111111111',(select id from rr))->>'status'),'refunded','late reject reports canonical settled result');
select is((public.reserve_latest_topup_refund('d1111111-1111-4111-8111-111111111111','refund-recovery-first',3000)->>'actualRefund'),'true','repeat reserve returns correct mode');
select is((public.get_wallet_balances('d1111111-1111-4111-8111-111111111111')->>'topupAvailable')::bigint,7000::bigint,'completed cancel does not debit twice');
select is((public.get_topup_refund_limits('d1111111-1111-4111-8111-111111111111')->>'maxRefundableTopup')::bigint,7000::bigint,'original payment remaining caps next refund');
select is((public.reserve_latest_topup_refund('d1111111-1111-4111-8111-111111111111','refund-recovery-next',2000)->>'status'),'reserved','next partial refund after completion');
create temporary table rr2 as select id from public.wallet_transactions where idempotency_key='refund-recovery-next';
select is((public.prepare_topup_refund('d1111111-1111-4111-8111-111111111111',(select id from rr2),'provider_test','{"balanceAmount":7000,"transactionKeys":["previous_key"]}'::jsonb)->>'canDispatch'),'true','next request has separate dispatch claim');
select throws_ok($$select public.complete_topup_refund('d1111111-1111-4111-8111-111111111111',(select id from rr2),jsonb_build_object('status','PARTIALLY_CANCELED','paymentKey','refund_original_payment','cancelAmount',2000,'transactionKey','refund_cancel_transaction','cancelReason','Mirujima refund '||(select id::text from rr2),'refundRequestId',(select id::text from rr2),'sandbox',false,'actualRefund',true,'providerMode','provider_test'))$$,'P0001','refund transaction already used','provider transaction cannot settle a second refund');
select is((public.get_wallet_balances('d1111111-1111-4111-8111-111111111111')->>'topupAvailable')::bigint,5000::bigint,'unresolved second cancellation remains reserved');
-- Real approval RPC stores provider_order_id on the request, not the posted credit.
insert into auth.users(id,email) values ('d3333333-3333-4333-8333-333333333333','refund-real-order@example.com');
update public.profiles set role='guardian' where id='d3333333-3333-4333-8333-333333333333';
set local request.jwt.claim.sub='d3333333-3333-4333-8333-333333333333';
select public.create_topup_payment_order('d3333333-3333-4333-8333-333333333333',10000,'refund-real-order-fixture');
create temporary table order_fixture as select provider_order_id from public.wallet_transactions where idempotency_key='refund-real-order-fixture';
select public.claim_topup_payment('d3333333-3333-4333-8333-333333333333',(select provider_order_id from order_fixture),'refund_real_payment',10000);
select public.confirm_toss_topup_payment('d3333333-3333-4333-8333-333333333333',(select provider_order_id from order_fixture),'refund_real_payment','{"status":"DONE"}'::jsonb);
select is((public.reserve_latest_topup_refund('d3333333-3333-4333-8333-333333333333','refund-real-request-fixture',3000)->>'originalOrderId'),(select provider_order_id from order_fixture),'real approved credit resolves original order through its canonical request');
select is((public.prepare_topup_refund('d3333333-3333-4333-8333-333333333333',(select id from public.wallet_transactions where idempotency_key='refund-real-request-fixture'),'provider_test','{"balanceAmount":10000,"transactionKeys":[]}'::jsonb)->>'canDispatch'),'true','real approval path supports provider cancellation');
select * from finish();
rollback;
